/**
 * Earth Layer Plugin Registry
 *
 * All built-in layers are registered here. Third-party layers can be added
 * by pushing an EarthLayerPlugin-conformant object to `EXTRA_PLUGINS` before
 * the app mounts, or by calling `registerPlugin()` at runtime.
 *
 * @example
 * import { registerPlugin } from './layerRegistry';
 * registerPlugin({
 *   id: 'shipping-lanes',
 *   label: '🚢 Shipping',
 *   title: 'Live vessel traffic — MarineTraffic',
 *   defaultEnabled: false,
 *   component: ShippingLayer,
 * });
 */

import type React from 'react';
import type { EarthLayerPlugin, EarthLayerProps } from '@atlantis/shared';

// Built-in layer components (imported lazily to keep the registry decoupled)
import { TerminatorLayer }   from './TerminatorLayer';
import { WeatherRadarLayer } from './WeatherRadarLayer';
import { EarthquakeLayer }   from './EarthquakeLayer';
import { AuroraLayer }       from './AuroraLayer';
import { FireLayer }         from './FireLayer';
import { FlightLayer }       from './FlightLayer';
import { ISSLayer }          from './ISSLayer';
import { MeasureLayer }      from './MeasureLayer';

// ─── Built-in plugins ─────────────────────────────────────────────────────────

const BUILTIN_PLUGINS: EarthLayerPlugin[] = [
  {
    id:             'night',
    label:          '🌑 Night',
    title:          'Day/night terminator',
    defaultEnabled: false,
    component:      TerminatorLayer,
  },
  {
    id:             'aurora',
    label:          '🌌 Aurora',
    title:          'Aurora forecast — NOAA SWPC',
    defaultEnabled: false,
    component:      AuroraLayer,
  },
  {
    id:             'iss',
    label:          '🛸 ISS',
    title:          'ISS live position + footprint',
    defaultEnabled: false,
    component:      ISSLayer,
  },
  {
    id:             'quakes',
    label:          '🌍 Quakes',
    title:          'Earthquakes — USGS past month',
    defaultEnabled: false,
    component:      EarthquakeLayer,
  },
  {
    id:             'fires',
    label:          '🔥 Fires',
    title:          'Active wildfires — NASA EONET',
    defaultEnabled: false,
    component:      FireLayer,
  },
  {
    id:             'radar',
    label:          '🌧 Radar',
    title:          'Weather radar — RainViewer',
    defaultEnabled: false,
    component:      WeatherRadarLayer,
  },
  {
    id:             'flights',
    label:          '✈ Flights',
    title:          'Live flight traffic — altitude-coded',
    defaultEnabled: false,
    // FlightLayer declares an extra `zoom` prop (injected in App.tsx); cast to the
    // base plugin signature since registry consumers forward unknown extras.
    component:      FlightLayer as unknown as React.ComponentType<EarthLayerProps>,
  },
  {
    id:             'measure',
    label:          '📏 Measure',
    title:          'Click two points to measure great-circle distance',
    defaultEnabled: false,
    component:      MeasureLayer,
  },
];

// ─── Registry ─────────────────────────────────────────────────────────────────

const _registry = new Map<string, EarthLayerPlugin>(
  BUILTIN_PLUGINS.map((p) => [p.id, p]),
);

/** Register a new layer plugin. Overwrites any existing plugin with the same id. */
export function registerPlugin(plugin: EarthLayerPlugin): void {
  _registry.set(plugin.id, plugin);
}

/** Unregister a plugin by id. */
export function unregisterPlugin(id: string): void {
  _registry.delete(id);
}

/** Return all currently registered plugins in insertion order. */
export function getPlugins(): EarthLayerPlugin[] {
  return Array.from(_registry.values());
}

/** Return a single plugin by id, or undefined. */
export function getPlugin(id: string): EarthLayerPlugin | undefined {
  return _registry.get(id);
}
