import { useCallback, useEffect, useRef } from 'react';

// ─── Airplanes.live (free, no auth, CORS-enabled) ────────────────────────────
const ADSB_BASE  = 'https://api.airplanes.live/v2';
const MAX_NM     = 250;
const REFRESH_MS = 20_000;
const TRAIL_MAX  = 15;  // position history per aircraft
const STALE_MS   = 2.5 * REFRESH_MS; // prune if not seen within this window

// ADS-B aircraft object (relevant fields only)
interface AircraftRaw {
  hex:        string;
  flight?:    string;
  lat?:       number;
  lon?:       number;
  alt_baro?:  number | 'ground';
  gs?:        number;   // ground speed, knots
  track?:     number;   // true track, degrees
  baro_rate?: number;   // ft/min
  r?:         string;   // registration
  t?:         string;   // aircraft type
}

interface Flight {
  icao24:   string;
  callsign: string | null;
  lat:      number;
  lon:      number;
  altFt:    number | null;
  speedKts: number | null;
  heading:  number | null;
  vrateFpm: number | null;
  reg:      string | null;
  type:     string | null;
}

function parseAircraft(raw: AircraftRaw): Flight | null {
  if (raw.lat == null || raw.lon == null) return null;
  return {
    icao24:   raw.hex,
    callsign: raw.flight?.trim() || null,
    lat:      raw.lat,
    lon:      raw.lon,
    altFt:    typeof raw.alt_baro === 'number' ? raw.alt_baro : null,
    speedKts: raw.gs ?? null,
    heading:  raw.track ?? null,
    vrateFpm: raw.baro_rate ?? null,
    reg:      raw.r ?? null,
    type:     raw.t ?? null,
  };
}

// ─── Altitude color ───────────────────────────────────────────────────────────
function altColor(altFt: number | null): string {
  if (altFt == null || altFt < 1_000) return '#8b949e'; // ground / low — grey
  if (altFt < 10_000)                 return '#f0883e'; // departure/approach — orange
  if (altFt < 25_000)                 return '#d29922'; // low cruise — amber
  return '#58a6ff';                                      // cruise — blue
}

// SVG plane icon rotated by heading, coloured by altitude
function planeIconHtml(heading: number, color: string, followed: boolean): string {
  const glow = followed
    ? `filter:drop-shadow(0 0 5px ${color}) drop-shadow(0 0 10px ${color});`
    : `filter:drop-shadow(0 1px 3px rgba(0,0,0,.9));`;
  return `<div style="
    width:22px;height:22px;
    display:flex;align-items:center;justify-content:center;
    transform:rotate(${heading}deg);
    ${glow}
    cursor:pointer;
    transition:transform .3s;
  ">
    <svg width="16" height="16" viewBox="0 0 24 24" fill="${color}">
      <path d="M21 16v-2l-8-5V3.5c0-.83-.67-1.5-1.5-1.5S10 2.67 10 3.5V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z"/>
    </svg>
  </div>`;
}

// ─── Viewport radius ──────────────────────────────────────────────────────────
function viewportRadiusNm(map: import('leaflet').Map): number {
  const bounds = map.getBounds();
  const center = map.getCenter();
  const corner = bounds.getNorthEast();
  const R  = 3440.065;
  const φ1 = (center.lat * Math.PI) / 180;
  const φ2 = (corner.lat * Math.PI) / 180;
  const Δφ = ((corner.lat - center.lat) * Math.PI) / 180;
  const Δλ = ((corner.lng - center.lng) * Math.PI) / 180;
  const a  = Math.sin(Δφ / 2) ** 2 + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) ** 2;
  const nm = 2 * R * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.min(Math.ceil(nm), MAX_NM);
}

// ─── Destination point from bearing + distance ────────────────────────────────
function destinationPoint(lat: number, lon: number, bearing: number, distKm: number): [number, number] {
  const R  = 6371;
  const d  = distKm / R;
  const φ1 = (lat     * Math.PI) / 180;
  const λ1 = (lon     * Math.PI) / 180;
  const θ  = (bearing * Math.PI) / 180;
  const φ2 = Math.asin(Math.sin(φ1) * Math.cos(d) + Math.cos(φ1) * Math.sin(d) * Math.cos(θ));
  const λ2 = λ1 + Math.atan2(Math.sin(θ) * Math.sin(d) * Math.cos(φ1), Math.cos(d) - Math.sin(φ1) * Math.sin(φ2));
  return [(φ2 * 180) / Math.PI, (λ2 * 180) / Math.PI];
}

// ─── Popup HTML ───────────────────────────────────────────────────────────────
function popupHtml(f: Flight): string {
  const color  = altColor(f.altFt);
  const altM   = f.altFt   != null ? `${Math.round(f.altFt * 0.3048).toLocaleString()} m` : '—';
  const spdKm  = f.speedKts != null ? `${Math.round(f.speedKts * 1.852)} km/h` : '—';
  const hdg    = f.heading  != null ? `${Math.round(f.heading)}°` : '—';
  const vr     = f.vrateFpm != null
    ? `${f.vrateFpm > 0 ? '↑' : '↓'} ${Math.abs(Math.round(f.vrateFpm * 0.00508))} m/s`
    : '—';
  return `
    <div style="font-family:monospace;font-size:12px;line-height:1.75;min-width:180px;">
      <div style="font-weight:700;font-size:13px;margin-bottom:4px;color:${color}">
        ✈ ${f.callsign ?? f.icao24}${f.reg ? ` · ${f.reg}` : ''}
      </div>
      ${f.type ? `<div>🛩 ${f.type}</div>` : ''}
      <div>📡 ${f.icao24}</div>
      <div>↑ Altitude: ${altM}</div>
      <div>→ Speed: ${spdKm}</div>
      <div>⬆ Heading: ${hdg}</div>
      <div>${vr}</div>
      <div style="margin-top:6px">
        <button
          onclick="window.__atlantisFlightFollow && window.__atlantisFlightFollow('${f.icao24}')"
          style="
            padding:3px 10px;cursor:pointer;
            background:rgba(88,166,255,.12);
            border:1px solid #58a6ff;
            border-radius:4px;
            color:#58a6ff;
            font-family:monospace;font-size:11px;
          ">📍 Follow</button>
      </div>
    </div>`;
}

// ─── Component ────────────────────────────────────────────────────────────────
const MIN_ZOOM = 5;

interface FlightLayerProps {
  map:     import('leaflet').Map | null;
  enabled: boolean;
  zoom:    number;
}

export function FlightLayer({ map, enabled, zoom }: FlightLayerProps) {
  const markersRef    = useRef<Map<string, import('leaflet').Marker>>(new Map());
  const projLinesRef  = useRef<Map<string, import('leaflet').Polyline>>(new Map()); // 30-min prediction
  const trailLinesRef = useRef<Map<string, import('leaflet').Polyline>>(new Map()); // position history
  const trailsRef     = useRef<Map<string, [number, number][]>>(new Map());
  const lastSeenRef   = useRef<Map<string, number>>(new Map());
  const abortRef      = useRef<AbortController | null>(null);
  const followedRef   = useRef<string | null>(null);

  // Register global follow handler (used by popup button)
  useEffect(() => {
    (window as any).__atlantisFlightFollow = (icao: string) => {
      followedRef.current = followedRef.current === icao ? null : icao;
    };
    return () => { delete (window as any).__atlantisFlightFollow; };
  }, []);

  const clearAll = useCallback(() => {
    markersRef.current.forEach((m) => m.remove());
    markersRef.current.clear();
    projLinesRef.current.forEach((l) => l.remove());
    projLinesRef.current.clear();
    trailLinesRef.current.forEach((l) => l.remove());
    trailLinesRef.current.clear();
    trailsRef.current.clear();
    lastSeenRef.current.clear();
    followedRef.current = null;
  }, []);

  const fetchAndRender = useCallback(async () => {
    if (!map || !enabled || zoom < MIN_ZOOM) return;

    const center   = map.getCenter();
    const radiusNm = viewportRadiusNm(map);
    const url      = `${ADSB_BASE}/point/${center.lat.toFixed(4)}/${center.lng.toFixed(4)}/${radiusNm}`;

    abortRef.current?.abort();
    abortRef.current = new AbortController();

    try {
      const res = await fetch(url, { signal: abortRef.current.signal });
      if (!res.ok) return;
      const data = await res.json() as { ac?: AircraftRaw[] };
      if (!map || !enabled) return;

      const L   = window.L;
      const now = Date.now();

      for (const raw of data.ac ?? []) {
        const f = parseAircraft(raw);
        if (!f || f.altFt == null) continue;

        const heading  = f.heading ?? 0;
        const color    = altColor(f.altFt);
        const followed = followedRef.current === f.icao24;
        const icon     = L.divIcon({
          html:       planeIconHtml(heading, color, followed),
          className:  '',
          iconSize:   [22, 22],
          iconAnchor: [11, 11],
        });

        // Update trail
        const prevTrail = trailsRef.current.get(f.icao24) ?? [];
        const newTrail  = [...prevTrail, [f.lat, f.lon] as [number, number]].slice(-TRAIL_MAX);
        trailsRef.current.set(f.icao24, newTrail);
        lastSeenRef.current.set(f.icao24, now);

        // 30-min projected trajectory
        const canProject        = f.speedKts != null && f.heading != null;
        const distKm            = canProject ? (f.speedKts! * 1.852 * 0.5) : 0;
        const [endLat, endLon]  = canProject
          ? destinationPoint(f.lat, f.lon, f.heading!, distKm)
          : [f.lat, f.lon];

        const existing = markersRef.current.get(f.icao24);
        if (existing) {
          existing.setLatLng([f.lat, f.lon]);
          existing.setIcon(icon);
          existing.getPopup()?.setContent(popupHtml(f));
          projLinesRef.current.get(f.icao24)?.setLatLngs([[f.lat, f.lon], [endLat, endLon]]);
          trailLinesRef.current.get(f.icao24)?.setLatLngs(newTrail);
        } else {
          // New aircraft
          const marker = L.marker([f.lat, f.lon], { icon });
          marker.bindPopup(popupHtml(f), { maxWidth: 240 });
          marker.addTo(map);
          markersRef.current.set(f.icao24, marker);

          if (canProject) {
            const projLine = L.polyline(
              [[f.lat, f.lon], [endLat, endLon]],
              { color, weight: 1.5, opacity: 0.35, dashArray: '4 7', interactive: false },
            );
            projLine.addTo(map);
            projLinesRef.current.set(f.icao24, projLine);
          }

          if (newTrail.length > 1) {
            const trail = L.polyline(newTrail, {
              color,
              weight:      1.5,
              opacity:     0.45,
              interactive: false,
            });
            trail.addTo(map);
            trailLinesRef.current.set(f.icao24, trail);
          }
        }
      }

      // Prune aircraft not seen within STALE_MS
      markersRef.current.forEach((marker, icao) => {
        const lastSeen = lastSeenRef.current.get(icao) ?? 0;
        if (now - lastSeen > STALE_MS) {
          marker.remove();
          markersRef.current.delete(icao);
          projLinesRef.current.get(icao)?.remove();
          projLinesRef.current.delete(icao);
          trailLinesRef.current.get(icao)?.remove();
          trailLinesRef.current.delete(icao);
          trailsRef.current.delete(icao);
          lastSeenRef.current.delete(icao);
          if (followedRef.current === icao) followedRef.current = null;
        }
      });

      // Pan to followed aircraft
      if (followedRef.current) {
        const m = markersRef.current.get(followedRef.current);
        if (m) map.panTo(m.getLatLng(), { animate: true, duration: 0.5 });
      }
    } catch (err) {
      if (err instanceof Error && err.name === 'AbortError') return;
    }
  }, [map, enabled, zoom]);

  // Enable / disable / zoom gate
  useEffect(() => {
    if (!enabled || zoom < MIN_ZOOM) {
      clearAll();
      return;
    }

    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    const tick = async () => {
      await fetchAndRender();
      if (!cancelled) timer = setTimeout(tick, REFRESH_MS);
    };
    tick();

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [enabled, fetchAndRender, clearAll]);

  // Re-fetch on pan / zoom (debounced)
  useEffect(() => {
    if (!map || !enabled) return;
    let debounce: ReturnType<typeof setTimeout>;
    const onMove = () => {
      clearTimeout(debounce);
      debounce = setTimeout(fetchAndRender, 1200);
    };
    map.on('moveend', onMove);
    return () => {
      clearTimeout(debounce);
      map.off('moveend', onMove);
    };
  }, [map, enabled, fetchAndRender]);

  return null;
}
